function generatePermutations(str) {
    const results = [];
    function permute(current, remaining) {
        if (remaining.length === 0) {
            results.push(current);
            return;
        }
        for (let i = 0; i < remaining.length; i++) {
            permute(
                current + remaining[i],
                remaining.slice(0, i) + remaining.slice(i + 1)
            );
        }
    }
    permute('', str);
    return results;
}

